// Кейсы REC-022…REC-024 (REC-025 — сама очистка и опрос старой ссылки — ТОЛЬКО ВРУЧНУЮ: необратимо, нужен звонок и флаг «עסק בדיקה»).
// Всё — только чтение готовых данных 21.10 → @prod-safe, без @data, без очистки:
//  - QA-8eb9d8-2110 (5dc4bdba…, попытка f23f1072, запись 230865a0…) очищен «ניקוי 90 יום» 21.10 18:15 — НЕ удалять;
//  - QA-C4-2110-D2 (запись 0b8d3dfc) — целая запись для проверки заголовков кэша — НЕ удалять.
// Окружение: QA_8EB9D8_PURGED_CANDIDATE_ID, QA_8EB9D8_PURGED_RECORDING_ID, QA_8EB9D8_INTACT_CANDIDATE.
// Отчёт business и журнал SA — только десктоп (L-20261014-5).
import { test, expect } from '../../fixtures';
import { openWithApi, Api, SUPABASE_URL } from '../support/api';

const HASH = '#8eb9d8 · #b086024193665fbc0b8eb9d8';
const PURGED_ID = process.env.QA_8EB9D8_PURGED_CANDIDATE_ID || '5dc4bdba-df4f-4dcd-859b-2333c98578c1';
const PURGED_RECORDING = process.env.QA_8EB9D8_PURGED_RECORDING_ID || '230865a0-3a45-4e4a-a643-fae9e90da958';
const INTACT = process.env.QA_8EB9D8_INTACT_CANDIDATE || 'QA-C4-2110-D2';
const RECORDING_URL = `${SUPABASE_URL}/functions/v1/get-recording-url`;

type Report = {
  attempt?: { id: string; content_erased_at?: string | null } | null;
  recording?: { id: string } | null;
  transcript?: unknown;
  report?: unknown;
};

async function getReport(api: Api, id: string): Promise<Report> {
  const res = await api.rpc('get_candidate_report', { p_candidate_id: id, p_reason: null });
  expect(res.ok(), `get_candidate_report ${res.status()}`).toBeTruthy();
  const j = await res.json();
  return (Array.isArray(j) ? j[0] : j) as Report;
}

test.describe(`Удалённая запись недоступна по ранее выданной ссылке (${HASH})`, () => {
  test(`QA-8eb9d8-2110 после «ניקוי 90 יום»: в отчёте «ההקלטה של השיחה נמחקה.» и «התמלול נמחק יחד עם ההקלטה.», плеера нет; get-recording-url → 404 not_found @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    const api = await openWithApi(page, '/candidates');

    // Источник: F-56 AC8 «לאחר המחיקה כל קישור או כתובת חתומה שהפנו לתוכן מפסיקים לפעול».
    const rep = await getReport(api, PURGED_ID);
    expect(rep.attempt?.content_erased_at, 'attempt.content_erased_at — очистка 21.10').toBeTruthy();
    expect(rep.recording, 'recording после очистки').toBeNull();
    expect(rep.transcript, 'transcript после очистки').toBeNull();

    // Источник: AC тикета «אחרי מחיקת הקלטה אי אפשר להוריד אותה דרך כתובת שהופקה לפני המחיקה» — новую ссылку тоже не выдать.
    const res = await page.request.post(RECORDING_URL, { headers: api.headers, data: { recording_id: PURGED_RECORDING } });
    const body = await res.text();
    expect(res.status(), body).toBe(404);
    expect(JSON.parse(body)).toEqual({ error: 'not_found' });

    await page.goto(`/candidates/${PURGED_ID}/report`);
    await expect(page.getByText('ההקלטה של השיחה נמחקה.')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('התמלול נמחק יחד עם ההקלטה.')).toBeVisible();
    await expect(page.getByText('התוכן של השיחה נמחק')).toBeVisible();
    await expect(page.getByTestId('recording-player')).toHaveCount(0);
    await expect(page.locator('audio')).toHaveCount(0);
  });

  test(`журнал доступа: у QA-8eb9d8-2110 есть «הפעלת ניקוי 90 יום על רשומה» и «מחיקה בניקוי 90 יום» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('admin');
    await page.goto('/admin/access-log');
    await expect(page.getByRole('heading', { level: 1, name: 'רישום גישה' })).toBeVisible({ timeout: 30_000 });

    // Поле «מזהה מועמד» (ACL-007); селектор не проверен в браузере (решение пользователя: без браузера).
    await page.getByLabel('מזהה מועמד').or(page.getByPlaceholder(/מזהה מועמד/)).first().fill(PURGED_ID);
    const resp = page.waitForResponse((r) => r.url().includes('/rpc/admin_list_access_log') && r.request().method() === 'POST');
    await page.getByRole('button', { name: 'סינון', exact: true }).click();
    expect((await resp).ok(), 'admin_list_access_log').toBeTruthy();

    // Источник: факт 21.10 (скриншот 8eb9d8-PURGE-08) — очистка и удаление фиксируются в журнале.
    const rows = page.locator('main table tbody tr');
    await expect(rows.filter({ hasText: 'מחיקה בניקוי 90 יום' }).first()).toBeVisible();
    await expect(rows.filter({ hasText: 'הפעלת ניקוי 90 יום על רשומה' }).first()).toBeVisible();
  });

  test(`${INTACT}: подписанная ссылка на запись — cache-control private, no-store; повторный GET не из кэша CDN (не HIT, без age) @desktop @prod-safe ${HASH}`, async ({ asUser, playwright }) => {
    const page = await asUser('business');
    const api = await openWithApi(page, '/candidates');
    const rows = (await (await api.rpc('list_candidates')).json()) as { id: string; full_name: string }[];
    const c = rows.filter((r) => r.full_name === INTACT);
    expect(c, `кандидат «${INTACT}» (QA_8EB9D8_INTACT_CANDIDATE)`).toHaveLength(1);
    const rep = await getReport(api, c[0].id);
    expect(rep.recording?.id, `у ${INTACT} нет записи`).toBeTruthy();

    const res = await page.request.post(RECORDING_URL, { headers: api.headers, data: { recording_id: rep.recording!.id } });
    expect(res.status(), await res.text()).toBe(200);
    const { signed_url, expires_in } = (await res.json()) as { signed_url: string; expires_in: number };
    expect(signed_url, 'signed_url').toBeTruthy();
    // Источник: F-36 «נגישה רק דרך כתובת חתומה מוגבלת בזמן» (факт 21.10: 600 с).
    expect(expires_in).toBeGreaterThan(0);
    expect(expires_in).toBeLessThanOrEqual(600);

    // Ссылка — без авторизации (как у <audio>); отдельный контекст без сессии. Токен ссылки в отчёт не выводится.
    const anon = await playwright.request.newContext();
    try {
      const url = new URL(signed_url, SUPABASE_URL).toString();
      for (const tag of ['первый GET', 'повторный GET']) {
        const r = await anon.get(url);
        const h = r.headers();
        const facts = `${tag}: status=${r.status()} cache-control=${h['cache-control']} cf-cache-status=${h['cf-cache-status']} age=${h['age']} x-vercel-cache=${h['x-vercel-cache']}`;
        // Источник: комментарий программиста «get-recording-url с no-store, CDN не кэширует»; AC тикета. Факт 21.10: private, no-store; DYNAMIC; без age.
        expect([200, 206], facts).toContain(r.status());
        expect(h['cache-control'] || '', facts).toContain('no-store');
        expect(h['cache-control'] || '', facts).toContain('private');
        expect((h['cf-cache-status'] || '').toUpperCase(), facts).not.toBe('HIT');
        expect((h['x-vercel-cache'] || '').toUpperCase(), facts).not.toBe('HIT');
        expect(Number(h['age'] || '0'), facts).toBe(0);
      }
    } finally {
      await anon.dispose();
    }
  });
});
